"""Theorem 1 power functional for the point-mass (Case 1) BONuS setting.

Two independent evaluations are produced:

1. ``theory_authors`` -- the authors' own released functional
   ``simulation/utils/theory.py::tdp_curve_asy`` (bonus branch: pi_1=pi_aug, pi_2=1).
2. ``theory_paper``   -- a from-scratch implementation of Definition 1 (BH TPR
   function, eq. (8)) together with the BONuS signal strength of eq. (14):

       mu_bonus = h^2 * gamma / sqrt(h^2 * gamma^2 + c / pi_aug)
       t*       = inf{ t : S0(t) / ((1-gamma) S0(t) + gamma S1(t)) <= q }
       TPR_BH   = S1(t*),   S0 = 1 - Phi(t),  S1 = 1 - Phi(t - mu_bonus)

Both are computed from the formulas; no numeric value is hard-coded.
"""

import os
import sys

import numpy as np
from scipy.optimize import brentq
from scipy.stats import norm

REPO_SIM = os.path.join(os.path.dirname(os.path.abspath(__file__)), "repo", "simulation")


# ----------------------------------------------------------------------------
# from-scratch implementation of the paper's formulas
# ----------------------------------------------------------------------------
def mu_bonus(gamma, c, h, pi_aug):
    """BONuS signal strength, eq. (14): h^2 gamma / sqrt(h^2 gamma^2 + c/pi_aug)."""
    denom = np.sqrt((h * gamma) ** 2 + c / pi_aug)
    return (h ** 2) * gamma / denom


def _bh_threshold(mu, gamma, q):
    """t* = inf{t : S0(t) / ((1-gamma) S0(t) + gamma S1(t)) <= q}  (Definition 1)."""
    def phi(t):
        s0 = norm.sf(t)
        s1 = norm.sf(t - mu)
        return s0 / ((1.0 - gamma) * s0 + gamma * s1)

    # phi is continuous and strictly decreasing from 1 (t -> -inf) to 0 (t -> +inf)
    lo, hi = -50.0, 50.0
    if phi(lo) <= q:
        return lo
    if phi(hi) > q:
        return hi
    return brentq(lambda t: phi(t) - q, lo, hi, xtol=1e-12, rtol=1e-14)


def tpr_bh(mu, gamma, q):
    """TPR_BH(N(0,1), N(mu,1), gamma) = S1(t*)."""
    t_star = _bh_threshold(mu, gamma, q)
    return float(norm.sf(t_star - mu))


def theory_paper(gamma, c, h, pi_aug, q):
    mu = float(mu_bonus(gamma, c, h, pi_aug))
    return {"mu_bonus": mu, "tpr_bh": tpr_bh(mu, gamma, q)}


# ----------------------------------------------------------------------------
# authors' released functional
# ----------------------------------------------------------------------------
def theory_authors(gamma, c, h, pi_aug, q):
    """Call simulation/utils/theory.py::tdp_curve_asy (bonus: pi_1=pi_aug, pi_2=1)."""
    if REPO_SIM not in sys.path:
        sys.path.insert(0, REPO_SIM)
    from utils.theory import mean_shift_function, tdp_curve_asy  # authors' code

    mu = float(mean_shift_function(pi_aug, 1.0, gamma, h, c))
    tpr = float(tdp_curve_asy(q, h, gamma, c, pi_aug, 1.0))
    return {"mu_bonus": mu, "tpr_bh": tpr}


def theory_finite_check(gamma, c, h, m, tilde_m, q):
    """Optional finite-m refinement from simulation/utils/theory_finite_fixed.py."""
    if REPO_SIM not in sys.path:
        sys.path.insert(0, REPO_SIM)
    try:
        from utils.theory_finite_fixed import bonus_tdp_curve
    except Exception:
        return None
    try:
        return float(bonus_tdp_curve(q, m, tilde_m, h, gamma, c))
    except Exception:
        return None


if __name__ == "__main__":
    g, c, h, pi, q = 0.2, 0.2, 4.0, 0.5, 0.1
    print("paper  :", theory_paper(g, c, h, pi, q))
    print("authors:", theory_authors(g, c, h, pi, q))
    print("finite :", theory_finite_check(g, c, h, 1000, 1000, q))

