"""Theorem 1 power functional for the point-mass (Case 1) BONuS setting.

Three evaluations are produced, all computed from formulas (nothing hard-coded):

1. ``theory_paper``      -- PRIMARY.  Definition 1 / eq. (8) of the paper, i.e.
   the threshold ratio G0bar(t) / ((1-gamma) G0bar(t) + gamma G1bar(t)) <= q,
   together with the BONuS signal strength of eq. (14).  This is also exactly
   the convention implemented in the authors' own plotting layer
   (plotting_code/figures_split_vs_bonus.R::TPR_BH_normal, which plots the
   Theorem 1 curve against the ``null_adaptive == FALSE`` simulation rows).

2. ``theory_authors_py`` -- SIDE VALUE.  simulation/utils/theory.py::tdp_curve_asy,
   whose ``power_BH`` puts an extra (1-gamma) weight on the null survival in the
   numerator.  That is the same functional evaluated at level q/(1-gamma), i.e.
   the null-proportion-adaptive BH variant (the driver's ``null_adaptive=TRUE``
   rows).  Reported so the definitional difference is documented, not hidden.

3. ``theory_finite``     -- SIDE VALUE.  the finite-m refinement from
   simulation/utils/theory_finite_fixed.py at (m, tilde_m) = (1000, 1000).

Formulas used (eq. (14) and Definition 1):

    mu_bonus = h^2 * gamma / sqrt(h^2 * gamma^2 + c / pi_aug)
    t*       = inf{ t : S0(t) / ((1-gamma) S0(t) + gamma S1(t)) <= q }
    TPR_BH   = S1(t*),   S0 = 1 - Phi(t),  S1 = 1 - Phi(t - mu_bonus)
"""

import os
import sys

import numpy as np
from scipy.optimize import brentq
from scipy.stats import norm

REPO_SIM = os.path.join(os.path.dirname(os.path.abspath(__file__)), "repo", "simulation")


# ----------------------------------------------------------------------------
# from-scratch implementation of the paper's Definition 1 + eq. (14)
# ----------------------------------------------------------------------------
def mu_bonus(gamma, c, h, pi_aug):
    """BONuS signal strength, eq. (14): h^2 gamma / sqrt(h^2 gamma^2 + c/pi_aug)."""
    return (h ** 2) * gamma / np.sqrt((h * gamma) ** 2 + c / pi_aug)


def _ratio(t, mu, gamma, null_weight=1.0):
    """S0(t) / ((1-gamma) S0(t) + gamma S1(t)); monotone decreasing in t for mu > 0."""
    s0 = norm.sf(t)
    if s0 <= 0.0:                      # both tails underflowed -> ratio tends to 0
        return 0.0
    s1 = norm.sf(t - mu)
    denom = (1.0 - gamma) * s0 + gamma * s1
    return (null_weight * s0) / denom


def _bh_threshold(mu, gamma, q, null_weight=1.0):
    """t* = inf{t : ratio(t) <= q}  (Definition 1, eq. (8))."""
    if mu <= 0:
        return np.inf
    if _ratio(0.0, mu, gamma, null_weight) <= q:
        return 0.0
    hi, step = 1.0, 1.0
    for _ in range(60):                # expand an upper bracket
        if _ratio(hi, mu, gamma, null_weight) <= q:
            break
        step *= 2.0
        hi += step
    else:
        return np.inf
    return brentq(lambda t: _ratio(t, mu, gamma, null_weight) - q, 0.0, hi,
                  xtol=1e-12, rtol=8.9e-16)


def tpr_bh(mu, gamma, q, null_weight=1.0):
    """TPR_BH(N(0,1), N(mu,1), gamma) = S1(t*)."""
    t_star = _bh_threshold(mu, gamma, q, null_weight)
    if not np.isfinite(t_star):
        return float("nan")
    return float(norm.sf(t_star - mu))


def theory_paper(gamma, c, h, pi_aug, q):
    """PRIMARY: Definition 1 (eq. 8) with the BONuS signal strength (eq. 14)."""
    mu = float(mu_bonus(gamma, c, h, pi_aug))
    return {"mu_bonus": mu, "t_star": float(_bh_threshold(mu, gamma, q)),
            "tpr_bh": tpr_bh(mu, gamma, q)}


def theory_authors_py(gamma, c, h, pi_aug, q):
    """SIDE VALUE: simulation/utils/theory.py::tdp_curve_asy (bonus branch)."""
    if REPO_SIM not in sys.path:
        sys.path.insert(0, REPO_SIM)
    from utils.theory import mean_shift_function, tdp_curve_asy  # authors' code

    mu = float(mean_shift_function(pi_aug, 1.0, gamma, h, c))
    return {"mu_bonus": mu, "tpr_bh": float(tdp_curve_asy(q, h, gamma, c, pi_aug, 1.0))}


def theory_finite(gamma, c, h, m, tilde_m, q):
    """SIDE VALUE: finite-m refinement from simulation/utils/theory_finite_fixed.py."""
    if REPO_SIM not in sys.path:
        sys.path.insert(0, REPO_SIM)
    try:
        from utils.theory_finite_fixed import bonus_tdp_curve
    except Exception:
        return None
    try:
        return float(bonus_tdp_curve(q, m, tilde_m, h, gamma, c))
    except Exception:
        return None


if __name__ == "__main__":
    g, c, h, pi, q = 0.2, 0.2, 4.0, 0.5, 0.1
    print("paper (Def. 1, eq. 8) :", theory_paper(g, c, h, pi, q))
    print("authors python theory :", theory_authors_py(g, c, h, pi, q))
    print("finite-m refinement   :", theory_finite(g, c, h, 1000, 1000, q))

